#include <bits/stdc++.h>
using namespace std;

const int MAXA = 100011;
const int MAXB = 32;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b, n;
    cin >> a >> b >> n;

    int dp[MAXB] = {};

    for (int i = MAXA - 1; i >= a; --i) {
        for (int j = MAXB - 1; j >= 0; --j) {
            bool terminal = false;
            long long pw = 1;

            for (int k = 0; k < j; ++k) {
                pw *= i;
                if (pw >= n) {
                    terminal = true;
                    break;
                }
            }

            if (terminal) {
                dp[j] = 1;
                continue;
            }

            if (i == 1 && j == MAXB - 1) {
                dp[j] = 2;
                continue;
            }

            if (i == MAXA - 1 && j == 1) {
                dp[j] = ((n - MAXA + 1) % 2 != 0 ? 1 : 3);
                continue;
            }

            int mx = 1;

            if (i < MAXA - 1)
                mx = max(mx, dp[j]);

            if (j < MAXB - 1)
                mx = max(mx, dp[j + 1]);

            dp[j] = 4 - mx;
        }
    }

    if (dp[b] == 3)
        cout << "Stas";
    else if (dp[b] == 1)
        cout << "Masha";
    else
        cout << "Missing";

    return 0;
}

